from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    def extract_paren_groups(s):
        groups = []
        group = ''
        count = 0
        for char in s:
            if char == '(':
                count += 1
            elif char == ')':
                count -= 1
            group += char
            if count == 0:
                groups.append(group)
                group = ''
        return groups

    def remove_spaces(s):
        return s.replace(' ', '')

    groups = extract_paren_groups(paren_string)
    result = [remove_spaces(group) for group in groups]

    return result

